it('records explicit Shape confirmation in portable state and advances to Builder handoff', async () => {
    await runNativeCli(['new', 'confirmed-shape', '--runtime', 'compat', ...projectArgs()]);
    const paths = await nativeProjectPaths(projectRoot, 'docs');
    await fs.writeFile(path.join(paths.changesDir, 'confirmed-shape', 'brief.md'), brief);

    const early = json(
      await runNativeCli([
        'next',
        'confirmed-shape',
        '--summary',
        'The user confirmed too early',
        '--confirmed',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(early).toMatchObject({
      exitCode: 64,
      error: { message: expect.stringContaining('persisted Shape user confirmation boundary') },
    });
    await expect(readNativePortableChange(paths, 'confirmed-shape')).resolves.toMatchObject({
      phase: 'shape',
      status: 'active',
      state_version: 1,
    });

    expect((await prepareShape('confirmed-shape')).exitCode).toBe(0);

    const unguarded = json(
      await runNativeCli([
        'next',
        'confirmed-shape',
        '--summary',
        'The user confirmed without continuation guards',
        '--confirmed',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(unguarded).toMatchObject({
      exitCode: 64,
      error: {
        message: expect.stringContaining(
          '--expected-state-version and --expected-action are required for Shape confirmation',
        ),
      },
    });
    await expect(readNativePortableChange(paths, 'confirmed-shape')).resolves.toMatchObject({
      phase: 'shape',
      status: 'await-user',
      state_version: 2,
      loop: { next_action: 'confirm-shape' },
    });

    const result = json(
      await runNativeCli([
        'next',
        'confirmed-shape',
        '--summary',
        'The user confirmed the product decision',
        '--confirmed',
        '--expected-state-version',
        '2',
        '--expected-action',
        'confirm-shape',
        '--json',
        ...projectArgs(),
      ]),
    );

    expect(result).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'build',
          state_version: 3,
          loop: { stage: 'building', iteration: 1, next_action: 'submit-builder-candidate' },
          acceptance: { total: 1, pending: 1 },
        },
        continuation: { action: 'builder-handoff', runnerAction: { kind: 'builder-handoff' } },
      },
    });
    expect(JSON.stringify(result.data)).not.toContain('approval');
  });

